                args += self.transform_kwarg(k, v, split_single_char_options)
        return args

    @classmethod
    def _unpack_args(cls, arg_list: Sequence[Any]) -> List[str]:
        outlist = []
        for arg in arg_list:
            if isinstance(arg, (list, tuple)):
                outlist.extend(cls._unpack_args(arg))
            else:
                outlist.append(str(arg))
        return outlist

    @overload
    def _call_process(
        self, method: str, *args: None, **kwargs: None
    ) -> str: ...

    @overload
    def _call_process(
        self,
        method: str,
        istream: int,
        as_process: Literal[True],
        *args: Any,
        **kwargs: Any,
    ) -> "Git.AutoInterrupt": ...

    @overload
    def _call_process(
        self, method: str, *args: Any, **kwargs: Any
    ) -> Union[str, bytes, Tuple[int, Union[str, bytes], str], "Git.AutoInterrupt"]: ...

    def _call_process(
        self, method: str, *args: Any, **kwargs: Any
    ) -> Union[str, bytes, Tuple[int, Union[str, bytes], str], "Git.AutoInterrupt"]:
        """Run the given git command with the specified arguments and return the result."""
        exec_kwargs = {k: v for k, v in kwargs.items() if k in execute_kwargs}
        opts_kwargs = {k: v for k, v in kwargs.items() if k not in execute_kwargs}

        insert_after_this_arg = opts_kwargs.pop("insert_kwargs_after", None)

        opt_args = self.transform_kwargs(**opts_kwargs)
        ext_args = self._unpack_args([a for a in args if a is not None])

        if insert_after_this_arg is None:
            args_list = opt_args + ext_args
        else:
            index = ext_args.index(insert_after_this_arg)
            args_list = ext_args[: index + 1] + opt_args + ext_args[index + 1 :]

        call = [self.GIT_PYTHON_GIT_EXECUTABLE]
        call.extend(self._persistent_git_options)
        call.extend(self._git_options)
        self._git_options = ()

        call.append(dashify(method))
        call.extend(args_list)

        return self.execute(call, **exec_kwargs)

    def execute(self, call: List[str], **kwargs: Any) -> Union[str, bytes, Tuple[int, Union[str, bytes], str]]:
        """Execute the git command and return the result."""
        if self.GIT_PYTHON_TRACE:
            logging.debug(f"Executing command: {' '.join(call)}")
        if kwargs.get("stdout_as_string", False):
            kwargs["universal_newlines"] = True

        try:
            proc = subprocess.Popen(call, **kwargs)
        except OSError as e:
            if e.errno == e.ENOENT:
                raise GitCommandNotFound(f"Git command not found: {call[0]}")
            raise

        if kwargs.get("as_process", False):
            return Git.AutoInterrupt(proc)

        stdout, stderr = proc.communicate()

        if proc.returncode != 0:
            raise GitCommandError(call[0], proc.returncode, stdout, stderr)

        if kwargs.get("strip_newline_in_stdout", False):
            stdout = stdout.rstrip()

        return stdout

    class AutoInterrupt:
        """
        A class to automatically interrupt a subprocess when necessary.
        """

        _proc: Popen

        def __init__(self, proc: Popen):
            self._proc = proc

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc_value, traceback):
            self._proc.kill()
            self._proc.wait()

